<template>
  <component
    :is="embedded ? 'div' : 'section'"
    :class="['perf-panel', { 'perf-panel--embedded': embedded }]"
  >
    <!-- HEADER (standalone only) -->
    <div
      v-if="!embedded"
      class="perf-panel__header"
      @click="collapsed = !collapsed"
    >
      <h3 class="perf-panel__title">
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        >
          <line x1="18" y1="20" x2="18" y2="10" />
          <line x1="12" y1="20" x2="12" y2="4" />
          <line x1="6" y1="20" x2="6" y2="14" />
        </svg>
        Project Performance Analytics
      </h3>
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="18"
        height="18"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="2"
        stroke-linecap="round"
        stroke-linejoin="round"
        class="perf-panel__chevron"
        :class="{ 'perf-panel__chevron--rotated': collapsed }"
      >
        <polyline points="18 15 12 9 6 15" />
      </svg>
    </div>

    <div v-show="embedded || !collapsed">
      <!-- Filters Row -->
      <div class="perf-panel__date-filter-row">
        <div class="perf-panel__filters-bar">
          <div class="perf-panel__date-filter-inner">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
              class="perf-panel__date-icon"
            >
              <rect x="3" y="4" width="18" height="18" rx="2" ry="2" />
              <line x1="16" y1="2" x2="16" y2="6" />
              <line x1="8" y1="2" x2="8" y2="6" />
              <line x1="3" y1="10" x2="21" y2="10" />
            </svg>
            <div
              class="perf-panel__date-range"
              @click="showDatePicker = !showDatePicker"
            >
              <span class="perf-panel__date-range-value">{{
                perfDateFrom || "Start date"
              }}</span>
              <span class="perf-panel__date-range-arrow">→</span>
              <span class="perf-panel__date-range-value">{{
                perfDateTo || "End date"
              }}</span>
            </div>
            <button
              v-if="perfDateFrom || perfDateTo"
              class="perf-panel__date-range-clear"
              title="Clear dates"
              @click.stop="clearPerfDates"
            >
              ✕
            </button>
          </div>
          <div class="perf-panel__completion-filter">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
              class="perf-panel__filter-icon"
            >
              <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
            </svg>
            <span
              class="perf-panel__cr-badge"
              :class="{ 'perf-panel__cr-badge--active': completionRateFilter === '' }"
              @click="completionRateFilter = ''"
            >All</span>
            <span
              class="perf-panel__cr-badge perf-panel__cr-badge--red"
              :class="{ 'perf-panel__cr-badge--active': completionRateFilter === '0-25' }"
              @click="completionRateFilter = '0-25'"
            >0–25%</span>
            <span
              class="perf-panel__cr-badge perf-panel__cr-badge--orange"
              :class="{ 'perf-panel__cr-badge--active': completionRateFilter === '25-50' }"
              @click="completionRateFilter = '25-50'"
            >25–50%</span>
            <span
              class="perf-panel__cr-badge perf-panel__cr-badge--blue"
              :class="{ 'perf-panel__cr-badge--active': completionRateFilter === '50-75' }"
              @click="completionRateFilter = '50-75'"
            >50–75%</span>
            <span
              class="perf-panel__cr-badge perf-panel__cr-badge--green"
              :class="{ 'perf-panel__cr-badge--active': completionRateFilter === '75-100' }"
              @click="completionRateFilter = '75-100'"
            >75–100%</span>
          </div>
          <div v-if="showAssignees" class="perf-panel__member-scope">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="14"
              height="14"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              stroke-width="2"
              stroke-linecap="round"
              stroke-linejoin="round"
              class="perf-panel__filter-icon"
            >
              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
              <circle cx="9" cy="7" r="4" />
              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
            </svg>
            <select
              v-model="memberFilter"
              class="iz-select iz-select--sm perf-panel__member-scope-select"
              aria-label="Scope the panel to one member"
            >
              <option value="">All members</option>
              <option
                v-for="m in memberFilterOptions"
                :key="'mfo-' + m.userId"
                :value="m.userId"
              >
                {{ m.displayName || m.userId }}
              </option>
            </select>
            <button
              v-if="memberFilter"
              class="perf-panel__date-range-clear"
              title="Clear member filter"
              @click.stop="memberFilter = ''"
            >
              ✕
            </button>
          </div>
        </div>
        <div
          v-if="showDatePicker"
          v-click-outside="closePerfDatePicker"
          class="perf-panel__date-picker-dropdown"
        >
          <div class="perf-panel__date-picker-months">
            <div class="perf-panel__date-picker-month">
              <div class="perf-panel__date-picker-header">
                <button
                  class="perf-panel__date-picker-nav"
                  @click.stop="shiftPerfCalendar(-1)"
                >
                  ‹
                </button>
                <span class="perf-panel__date-picker-title">{{
                  perfCalendarLabel(0)
                }}</span>
                <span></span>
              </div>
              <div class="perf-panel__date-picker-grid">
                <span
                  v-for="d in ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']"
                  :key="d"
                  class="perf-panel__date-picker-dow"
                  >{{ d }}</span
                >
                <span
                  v-for="(cell, ci) in perfCalendarCells(0)"
                  :key="'PL' + ci"
                  :class="perfDateCellClass(cell)"
                  @click.stop="cell.date && pickPerfDate(cell.date)"
                  >{{ cell.day }}</span
                >
              </div>
            </div>
            <div class="perf-panel__date-picker-month">
              <div class="perf-panel__date-picker-header">
                <span></span>
                <span class="perf-panel__date-picker-title">{{
                  perfCalendarLabel(1)
                }}</span>
                <button
                  class="perf-panel__date-picker-nav"
                  @click.stop="shiftPerfCalendar(1)"
                >
                  ›
                </button>
              </div>
              <div class="perf-panel__date-picker-grid">
                <span
                  v-for="d in ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']"
                  :key="d"
                  class="perf-panel__date-picker-dow"
                  >{{ d }}</span
                >
                <span
                  v-for="(cell, ci) in perfCalendarCells(1)"
                  :key="'PR' + ci"
                  :class="perfDateCellClass(cell)"
                  @click.stop="cell.date && pickPerfDate(cell.date)"
                  >{{ cell.day }}</span
                >
              </div>
            </div>
          </div>
          <div class="perf-panel__date-picker-footer">
            <button
              class="perf-panel__date-picker-btn"
              @click.stop="
                perfDateFrom = '';
                perfDateTo = '';
                perfDateStep = 'from';
              "
            >
              Clear
            </button>
            <button
              class="perf-panel__date-picker-btn perf-panel__date-picker-btn--apply"
              @click.stop="showDatePicker = false"
            >
              Apply
            </button>
          </div>
        </div>
      </div>

      <!-- TOP ROW: Progress + Productivity -->
      <div
        :class="[
          'perf-panel__top-grid',
          { 'perf-panel__top-grid--single': !showMemberPerformance },
        ]"
      >
        <!-- Project Progress Comparison -->
        <div
          class="perf-panel__card perf-panel__card--clickable"
          @click="openModal('progress')"
        >
          <div class="perf-panel__card-header-row">
            <h3 class="perf-panel__card-title">
              Project Progress<br />Comparison
            </h3>
            <span class="perf-panel__card-drill" title="Click for details">
              <svg
                xmlns="http://www.w3.org/2000/svg"
                width="16"
                height="16"
                viewBox="0 0 24 24"
                fill="none"
                stroke="currentColor"
                stroke-width="2"
                stroke-linecap="round"
                stroke-linejoin="round"
              >
                <polyline points="15 3 21 3 21 9" />
                <line x1="10" y1="14" x2="21" y2="3" />
                <path
                  d="M21 14v5a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h5"
                />
              </svg>
            </span>
          </div>
          <div class="perf-panel__card-title-underline"></div>
          <div class="perf-panel__bar-list">
            <div
              v-for="(item, idx) in previewProjectProgress"
              :key="'prog-' + idx"
              class="perf-panel__bar-item"
            >
              <div class="perf-panel__bar-row">
                <span class="perf-panel__bar-label">{{ item.name }}</span>
                <span class="perf-panel__bar-value">{{ item.progress }}%</span>
              </div>
              <div class="perf-panel__bar-track">
                <div
                  class="perf-panel__bar-fill"
                  :style="{ width: item.progress + '%' }"
                ></div>
              </div>
            </div>
          </div>
          <div
            v-if="crFilteredProjectProgress.length > progressPreviewLimit"
            class="perf-panel__bar-hint"
          >
            Showing {{ previewProjectProgress.length }} of
            {{ crFilteredProjectProgress.length }} projects (click for full
            details)
          </div>
        </div>

