<script>
import DonutChart from "./DonutChart.vue";
import BarChart from "./BarChart.vue";
import AreaChart from "./AreaChart.vue";
import ProjectDetailsPanel from "./ProjectDetailsPanel.vue";

export default {
  name: "ProjectPerformancePanel",
  components: {
    DonutChart,
    BarChart,
    AreaChart,
    ProjectDetailsPanel,
  },
  directives: {
    "click-outside": {
      bind: function (el, binding) {
        el.__clickOutsideHandler = function (e) {
          if (!el.contains(e.target)) {
            binding.value(e);
          }
        };
        document.addEventListener("pointerdown", el.__clickOutsideHandler);
      },
      unbind: function (el) {
        document.removeEventListener("pointerdown", el.__clickOutsideHandler);
        delete el.__clickOutsideHandler;
      },
    },
  },
  props: {
    embedded: {
      type: Boolean,
      default: false,
    },
    projectProgress: {
      type: Array,
      required: true,
    },
    /* Still part of the panel's contract with Dashboard.vue, but the card
       no longer reads it: it needs per-project and per-status counts, which
       only performanceDetails.memberDetails carries. See memberRollup. */
    memberPerformance: {
      type: Array,
      required: true,
    },
    showMemberPerformance: {
      type: Boolean,
      default: true,
    },
    taskDelayProjects: {
      type: Array,
      required: true,
    },
    taskCompletionProjects: {
      type: Array,
      required: true,
    },
    performanceDetails: {
      type: Object,
      default: function () {
        return {
          progressDetails: [],
          memberDetails: [],
          delayDetails: [],
          completionDetails: [],
        };
      },
    },
    projectDetails: {
      type: Array,
      default: function () {
        return [];
      },
    },
    /* Org-wide upcoming meetings. Empty in the public share view, which never
       fetches them; the card there is hidden by showAssignees instead. */
    upcomingEvents: {
      type: Array,
      default: function () {
        return [];
      },
    },
    /* projectId => documents waiting on the viewer's signature. */
    projectSignatures: {
      type: Object,
      default: function () {
        return {};
      },
    },
    showTeamWorkload: {
      type: Boolean,
      default: true,
    },
    showAssignees: {
      type: Boolean,
      default: true,
    },
    orgMembers: {
      type: Array,
      default: function () {
        return [];
      },
    },
  },
  data: function () {
    return {
      collapsed: true,
      delayIndex: 0,
      completionIndex: 0,
      modal: null,
      expandedProjects: {},
      delaySortBy: "latest",
      progressSortBy: "desc",
      completionSortBy: "desc",
      delaySearch: "",
      completionSearch: "",
      delayStatusFilter: "",
      completionStatusFilter: "",
      completionRateFilter: "",
      delayChartMode: "donut",
      delayChartRenderKey: 0,
      // Date range filter
      perfDateFrom: "",
      perfDateTo: "",
      showDatePicker: false,
      perfDateStep: "from",
      perfCalendarBase: new Date(),
      // Global member scope (Filters Row) — see hasScopeFilter
      memberFilter: "",
      // Member Performance card filters
      memberSearch: "",
      memberProject: "all",
      memberBucket: "all",
    };
  },
  computed: {
    progressPreviewLimit: function () {
      return 5;
    },
    memberPreviewLimit: function () {
      return 5;
    },
    /* ── Member Performance card ──────────────────────────────────
       Rolled up from memberDetails, not from the memberPerformance prop:
       the card now shows per-project and per-status counts, and
       memberDetails is the only shape carrying a task's project and due
       date. dateFilteredMemberDetails already applies the panel's date
       range, so the rollup inherits it.

       Archived tasks are left out of every bucket, and so out of the
       card's totals. DeckService::fetchTaskRowsForBoards tests archived
       BEFORE the Approved/Done stack, so a finished card that someone
       archived reads as 'archived', never 'done' — counting those would
       let tidying up a board drag a member's completion rate down. */
    memberBuckets: function () {
      return [
        { key: "done", label: "Done", color: "var(--color-success)" },
        { key: "progress", label: "In progress", color: "var(--chart-5)" },
        { key: "overdue", label: "Overdue", color: "var(--color-danger)" },
      ];
    },
    memberRollup: function () {
      /* Date-only string compare, matching the CAST(duedate AS DATE) the
         SQL uses. Parsing to Date would read 'YYYY-MM-DD' as UTC midnight
         and compare it against local midnight — an off-by-one for anyone
         east of Greenwich. */
      var now = new Date();
      var todayStr =
        now.getFullYear() +
        "-" +
        ("0" + (now.getMonth() + 1)).slice(-2) +
        "-" +
        ("0" + now.getDate()).slice(-2);

      var list = this.dateFilteredMemberDetails;
      var result = [];

      for (var i = 0; i < list.length; i++) {
        var mem = list[i];
        var byProject = {};
        var order = [];
        var counts = { done: 0, progress: 0, overdue: 0 };
        var total = 0;

        for (var j = 0; j < (mem.tasks || []).length; j++) {
          var t = mem.tasks[j];
          if (t.status === "archived") continue;

          var bucket = "progress";
          if (t.status === "done") {
            bucket = "done";
          } else if (t.due && String(t.due).substring(0, 10) < todayStr) {
            bucket = "overdue";
          }

          var name = t.project || "Unassigned project";
          if (!byProject[name]) {
            byProject[name] = {
              name: name,
              total: 0,
              done: 0,
              progress: 0,
              overdue: 0,
            };
            order.push(name);
          }
          byProject[name][bucket]++;
          byProject[name].total++;
          counts[bucket]++;
          total++;
        }

        if (total === 0) continue;

        result.push({
          name: mem.name,
          total: total,
          counts: counts,
          projects: order
            .map(function (n) {
              return byProject[n];
            })
            .sort(function (a, b) {
              return b.total - a.total;
            }),
        });
      }
      return result;
    },
    memberProjectOptions: function () {
      var seen = {};
      var out = [];
      this.memberRollup.forEach(function (mem) {
        mem.projects.forEach(function (p) {
          if (!seen[p.name]) {
            seen[p.name] = true;
            out.push(p.name);
          }
        });
      });
      return out.sort();
    },
    /* Chip counts answer "how much work is in this state?" for the
       current search and project, so they must not narrow themselves by
       the bucket already selected. */
    memberBucketTotals: function () {
      var self = this;
      var q = this.memberSearch.trim().toLowerCase();
      var totals = { all: 0, done: 0, progress: 0, overdue: 0 };

      this.memberRollup.forEach(function (mem) {
        if (q && mem.name.toLowerCase().indexOf(q) === -1) return;
        mem.projects.forEach(function (p) {
          if (self.memberProject !== "all" && p.name !== self.memberProject) {
            return;
          }
          totals.done += p.done;
          totals.progress += p.progress;
          totals.overdue += p.overdue;
          totals.all += p.total;
        });
      });
      return totals;
    },
    filteredMemberRollup: function () {
      var self = this;
      var q = this.memberSearch.trim().toLowerCase();
      var bucket = this.memberBucket;
      var rows = [];

      this.memberRollup.forEach(function (mem) {
        if (q && mem.name.toLowerCase().indexOf(q) === -1) return;

        var projects = [];
        var counts = { done: 0, progress: 0, overdue: 0 };
        var total = 0;

        mem.projects.forEach(function (p) {
          if (self.memberProject !== "all" && p.name !== self.memberProject) {
            return;
          }
          if (bucket !== "all" && p[bucket] === 0) return;
          projects.push(p);
          counts.done += p.done;
          counts.progress += p.progress;
          counts.overdue += p.overdue;
          total += p.total;
        });

        if (total === 0) return;
        rows.push({
          name: mem.name,
          total: total,
          counts: counts,
          projects: projects,
        });
      });

      rows.sort(function (a, b) {
        if (bucket !== "all") {
          var diff = b.counts[bucket] - a.counts[bucket];
          if (diff !== 0) return diff;
        }
        return b.total - a.total;
      });
      return rows;
    },
    previewMemberRollup: function () {
      return this.filteredMemberRollup.slice(0, this.memberPreviewLimit);
    },
    memberEmptyMessage: function () {
