        var done = 0;
        for (var j = 0; j < (proj.tasks || []).length; j++) {
          var t = proj.tasks[j];
          var ca = (t.created_at || "").substring(0, 10);
          if (from && ca < from) continue;
          if (to && ca > to) continue;
          if (!this.matchesMember(t)) continue;
          total++;
          if (t.status === "done") done++;
        }
        result.push({
          name: proj.name,
