<template>
  <div class="proj-details">
    <!-- ── #4: Project Selector → Tabbed pill strip ── -->
    <div class="proj-details__tabs">
      <div class="proj-details__tabs-toolbar">
        <input
          v-model="tabSearch"
          type="text"
          class="iz-input proj-details__tabs-search-input"
          placeholder="Search projects…"
        />
        <select
          v-model="tabStatusFilter"
          class="iz-select proj-details__tabs-status-select"
        >
          <option value="">All Statuses</option>
          <option value="Active">Active</option>
          <option value="Waiting on Customer">Waiting on Customer</option>
          <option value="On Hold">On Hold</option>
          <option value="Done">Done</option>
        </select>
        <select
          v-model="tabTaskDueFilter"
          class="iz-select proj-details__tabs-status-select"
        >
          <option value="">All Task Due</option>
          <option value="overdue">Has Overdue</option>
          <option value="today">Has Due Today</option>
          <option value="nextSevenDays">Has Upcoming</option>
          <option value="nodue">Has No Due Date</option>
        </select>
        <select
          v-model="tabTaskStatusFilter"
          class="iz-select proj-details__tabs-status-select"
        >
          <option value="">All Task Status</option>
          <option value="open">Has Open Tasks</option>
          <option value="done">Has Done Tasks</option>
        </select>
        <button
          v-if="
            tabSearch ||
            tabStatusFilter ||
            tabTaskDueFilter ||
            tabTaskStatusFilter
          "
          class="proj-details__tabs-clear"
          @click="clearProjectFilters"
        >
          ✕ Clear
        </button>
      </div>
      <div class="proj-details__tabs-strip">
        <button
          v-for="p in visibleProjects"
          :key="p.id"
          class="proj-details__tab"
          :class="{ 'proj-details__tab--active': selectedProjectId === p.id }"
          @click="selectedProjectId = p.id"
        >
          <span
            class="proj-details__tab-dot"
            :class="
              'proj-details__tab-dot--' +
              p.statusLabel.toLowerCase().replace(/ /g, '-')
            "
          ></span>
          <span class="proj-details__tab-name">{{ p.name }}</span>
          <span v-if="p.number" class="proj-details__tab-num">{{
            p.number
          }}</span>
        </button>
        <span v-if="projects.length === 0" class="proj-details__tabs-empty">
          No projects
        </span>
      </div>
    </div>

    <!-- Empty state -->
    <div v-if="!selectedProject" class="iz-empty proj-details__empty">
      <svg
        xmlns="http://www.w3.org/2000/svg"
        width="40"
        height="40"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        stroke-width="1.5"
        stroke-linecap="round"
        stroke-linejoin="round"
        class="proj-details__empty-icon"
      >
        <path
          d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"
        />
      </svg>
      <p class="proj-details__empty-text">
        Select a project above to view detailed analytics
      </p>
    </div>

    <!-- Detail content -->
    <template v-if="selectedProject">
      <!-- ── #5: Row 1 — Split Info: Project Overview + Client Contact ── -->
      <div class="proj-details__row proj-details__row--two">
        <!-- Project Overview -->
        <div class="proj-details__card">
          <div class="proj-details__card-header">
            <h4 class="proj-details__card-title">Project Overview</h4>
            <span
              class="proj-details__badge"
              :class="
                'proj-details__badge--' +
                selectedProject.statusLabel.toLowerCase().replace(/ /g, '-')
              "
              >{{ selectedProject.statusLabel }}</span
            >
          </div>
          <div class="proj-details__info-grid">
            <div class="proj-details__info-item">
              <span class="proj-details__info-label">Project Name</span>
              <span class="proj-details__info-value">{{
                selectedProject.name
              }}</span>
            </div>
            <div class="proj-details__info-item" v-if="selectedProject.number">
              <span class="proj-details__info-label">Project Number</span>
              <span class="proj-details__info-value">{{
                selectedProject.number
              }}</span>
            </div>
            <div
              class="proj-details__info-item"
              v-if="selectedProject.description"
            >
              <span class="proj-details__info-label">Description</span>
              <span class="proj-details__info-value">{{
                selectedProject.description
              }}</span>
            </div>
            <div
              class="proj-details__info-item"
              v-if="
                selectedProject.location && selectedProject.location !== ','
              "
            >
              <span class="proj-details__info-label">Project Location</span>
              <span class="proj-details__info-value">{{
                selectedProject.location
              }}</span>
            </div>
            <div class="proj-details__info-item">
              <span class="proj-details__info-label">Created</span>
              <span class="proj-details__info-value">{{
                formatDate(selectedProject.createdAt)
              }}</span>
            </div>
            <div class="proj-details__info-item">
              <span class="proj-details__info-label">Last Updated</span>
              <span class="proj-details__info-value">{{
                formatDate(selectedProject.updatedAt)
              }}</span>
            </div>
          </div>
          <!-- Compact Completion bar inside overview card -->
          <div class="proj-details__progress">
            <div class="proj-details__progress-header">
              <span class="proj-details__progress-label">Task Completion</span>
              <span class="proj-details__progress-pct"
                >{{ selectedProject.completionPct }}%</span
              >
            </div>
            <div class="proj-details__progress-bar">
              <div
                class="proj-details__progress-fill"
                :style="{ width: selectedProject.completionPct + '%' }"
                :class="{
                  'proj-details__progress-fill--low':
                    selectedProject.completionPct < 25,
                  'proj-details__progress-fill--mid':
                    selectedProject.completionPct >= 25 &&
                    selectedProject.completionPct < 75,
                  'proj-details__progress-fill--high':
                    selectedProject.completionPct >= 75,
                }"
              ></div>
            </div>
            <span class="proj-details__progress-detail">
              {{ selectedProject.doneTasks }} of
              {{ selectedProject.totalTasks }} tasks completed
            </span>
          </div>
        </div>

        <!-- Client Contact + Resources -->
        <div class="proj-details__card">
          <h4 class="proj-details__card-title">Client &amp; Resources</h4>
          <div class="proj-details__info-grid" v-if="hasClientInfo">
            <div
              class="proj-details__info-item"
              v-if="selectedProject.clientName"
            >
              <span class="proj-details__info-label">Client</span>
              <span class="proj-details__info-value">{{
                selectedProject.clientName
              }}</span>
            </div>
            <div
              class="proj-details__info-item"
              v-if="selectedProject.clientEmail"
            >
              <span class="proj-details__info-label">Email</span>
              <a
                :href="'mailto:' + selectedProject.clientEmail"
                class="proj-details__info-link"
                >{{ selectedProject.clientEmail }}</a
              >
            </div>
            <div
              class="proj-details__info-item"
              v-if="selectedProject.clientPhone"
            >
              <span class="proj-details__info-label">Phone</span>
              <a
                :href="'tel:' + selectedProject.clientPhone"
                class="proj-details__info-link"
                >{{ selectedProject.clientPhone }}</a
              >
            </div>
            <div
              class="proj-details__info-item"
              v-if="selectedProject.clientAddress"
            >
              <span class="proj-details__info-label">Client Address</span>
              <span class="proj-details__info-value proj-details__info-value--multiline">{{
                selectedProject.clientAddress
              }}</span>
            </div>
          </div>
          <div v-else class="proj-details__no-client">
            No client information
          </div>
          <!-- Resource summary -->
          <h4 class="proj-details__card-title proj-details__card-title--sub">
            Resources
          </h4>
          <div class="proj-details__resources">
            <div class="proj-details__resource-item">
              <span class="proj-details__resource-value">{{
                selectedProject.resources.files
              }}</span>
              <span class="proj-details__resource-label">Files</span>
            </div>
            <div class="proj-details__resource-item">
              <span class="proj-details__resource-value">{{
                selectedProject.resources.whiteboards
              }}</span>
              <span class="proj-details__resource-label">Whiteboards</span>
            </div>
            <div class="proj-details__resource-item">
              <span class="proj-details__resource-value">{{
                selectedProject.resources.notes
              }}</span>
              <span class="proj-details__resource-label">Notes</span>
            </div>
          </div>
        </div>
      </div>

      <!-- ── Row 1b — Project Location Map ── -->
      <div class="proj-details__row">
        <div class="proj-details__card proj-details__card--full">
          <div class="proj-details__card-header">
            <h4 class="proj-details__card-title">Project Location</h4>
          </div>
          <ProjectMap
            v-if="geocodeStatus[selectedProject.id] === 'loaded' && geocodeByProject[selectedProject.id]"
            :lat="Number(geocodeByProject[selectedProject.id].lat)"
            :lng="Number(geocodeByProject[selectedProject.id].lng)"
            :display-name="geocodeByProject[selectedProject.id].displayName || null"
          />
          <div v-else-if="geocodeStatus[selectedProject.id] === 'loading'" class="proj-details__map-state">Loading map…</div>
          <div v-else-if="geocodeStatus[selectedProject.id] === 'no_address'" class="proj-details__map-state">No address available for this project.</div>
          <div v-else-if="geocodeStatus[selectedProject.id] === 'not_found'" class="proj-details__map-state">Couldn't locate this address on the map.</div>
          <div v-else-if="geocodeStatus[selectedProject.id] === 'unavailable'" class="proj-details__map-state proj-details__map-state--error">
            {{ geocodeError[selectedProject.id] || "Map unavailable." }}
          </div>
          <div v-else class="proj-details__map-state">Loading map…</div>
        </div>
      </div>

      <!-- ── #2 & #3: Row 2 — Donut (no table) + Due Dates + Team Workload ── -->
      <div
        class="proj-details__row"
        :class="showTeamWorkload ? 'proj-details__row--three' : 'proj-details__row--two'"
      >
        <!-- Task Distribution by Stack (donut only, no table) -->
        <div class="proj-details__card">
          <h4 class="proj-details__card-title">Task Distribution</h4>
          <div
            v-if="stackChartData.data.length > 0"
            class="proj-details__chart-wrap"
          >
            <DonutChart :chart-data="stackChartData" />
          </div>
          <div v-else class="proj-details__no-data">No tasks found</div>
        </div>

        <!-- Due Date Breakdown (standalone) -->
        <div class="proj-details__card">
          <h4 class="proj-details__card-title">Due Dates</h4>
          <div class="proj-details__due-grid">
            <div
              class="proj-details__due-item"
              :class="{
                'proj-details__due-item--danger': true,
                'proj-details__due-item--pulse':
                  selectedProject.dueStats.overdue > 0,
              }"
            >
              <span class="proj-details__due-value">{{
                selectedProject.dueStats.overdue
              }}</span>
              <span class="proj-details__due-label">Overdue</span>
            </div>
            <div class="proj-details__due-item proj-details__due-item--warning">
              <span class="proj-details__due-value">{{
                selectedProject.dueStats.today
              }}</span>
              <span class="proj-details__due-label">Due Today</span>
            </div>
            <div class="proj-details__due-item proj-details__due-item--info">
              <span class="proj-details__due-value">{{
                selectedProject.dueStats.upcoming
              }}</span>
              <span class="proj-details__due-label">Upcoming</span>
            </div>
            <div class="proj-details__due-item proj-details__due-item--muted">
              <span class="proj-details__due-value">{{
                selectedProject.dueStats.no_due
              }}</span>
              <span class="proj-details__due-label">No Due Date</span>
            </div>
          </div>
        </div>

        <!-- #2: Team Workload (separated assignees with progress bars) -->
        <div v-if="showTeamWorkload" class="proj-details__card">
          <h4 class="proj-details__card-title">Team Workload</h4>
          <div
            v-if="selectedProject.assignees.length > 0"
            class="proj-details__team-list"
          >
            <div
              v-for="(a, i) in selectedProject.assignees"
              :key="i"
              class="proj-details__team-member"
            >
              <div class="proj-details__team-row">
                <div class="proj-details__team-info">
                  <span class="iz-identity__avatar iz-identity__avatar--sm proj-details__team-avatar">{{
                    a.userId.charAt(0).toUpperCase()
                  }}</span>
                  <span class="proj-details__team-name">{{ a.userId }}</span>
                </div>
                <span class="proj-details__team-stats">
                  <span class="proj-details__team-count"
                    >{{ a.doneTasks || 0 }}/{{ a.tasks }}</span
                  >
                  <span class="proj-details__team-pct"
                    >{{ assigneePct(a) }}%</span
                  >
                </span>
              </div>
              <div class="proj-details__team-bar">
                <div
                  class="proj-details__team-bar-fill"
                  :style="{ width: assigneePct(a) + '%' }"
                ></div>
              </div>
            </div>
          </div>
          <div v-else class="proj-details__no-data">No team assignments</div>
        </div>
      </div>

      <!-- ── Row 2b — Per-project Timeline KPI ── -->
      <div
        class="proj-details__row proj-details__row--three proj-details__row--kpi"
      >
        <div class="proj-details__kpi-stat">
          <span class="proj-details__kpi-stat-value"
            >{{ selectedProject.completionPct }}%</span
          >
          <span class="proj-details__kpi-stat-label">Completion Rate</span>
          <div class="proj-details__kpi-bar">
            <div
              class="proj-details__kpi-bar-fill"
              :style="{ width: selectedProject.completionPct + '%' }"
              :class="{
                'proj-details__kpi-bar-fill--low':
                  selectedProject.completionPct < 25,
                'proj-details__kpi-bar-fill--mid':
                  selectedProject.completionPct >= 25 &&
                  selectedProject.completionPct < 75,
                'proj-details__kpi-bar-fill--high':
                  selectedProject.completionPct >= 75,
              }"
            ></div>
          </div>
          <span class="proj-details__kpi-stat-sub"
            >{{ selectedProject.doneTasks }}/{{
              selectedProject.totalTasks
            }}
            tasks</span
          >
        </div>
        <div class="proj-details__kpi-stat">
          <span class="proj-details__kpi-stat-value">{{
            coordinationPending
          }}</span>
          <span class="proj-details__kpi-stat-label">Coordination Pending</span>
          <span class="proj-details__kpi-stat-sub"
            >Weeks since Request Date</span
          >
        </div>
        <div class="proj-details__kpi-stat">
          <span class="proj-details__kpi-stat-value">{{
            requiredPrepTime
          }}</span>
          <span class="proj-details__kpi-stat-label">Required Prep Time</span>
          <span class="proj-details__kpi-stat-sub"
            >Planned preparation period</span
          >
        </div>
      </div>

      <!-- ── Row 2c — Upcoming Meetings (this project's team) ──
           Gated on showAssignees, the panel's existing "not the public share
           view" signal: the card keeps its empty state when the team has no
           meetings, and is absent entirely from a public link. -->
      <div v-if="showAssignees" class="proj-details__row">
        <div class="proj-details__card proj-details__card--full">
          <div class="proj-details__card-header">
            <h4 class="proj-details__card-title">
              Upcoming Meetings
              <span class="proj-details__count">{{ projectMeetings.length }}</span>
              <span
                v-if="!linkedMeetings.length"
                class="proj-details__card-hint"
              >the team's meetings — none are linked to this project</span>
            </h4>
          </div>
          <div
            v-if="projectMembersLoading[selectedProject.id]"
            class="proj-details__members-state"
          >Loading…</div>
          <UpcomingEventsPanel v-else :embedded="true" :events="projectMeetings" />
        </div>
      </div>

      <!-- ── Row 2d — Team Members (list + add + inline DRASCI edit) ── -->
      <div class="proj-details__row">
        <div class="proj-details__card proj-details__card--full">
          <div class="proj-details__card-header">
            <h4 class="proj-details__card-title">
              Team Members
              <span class="proj-details__count">{{
                projectMemberCount(selectedProject.id)
              }}</span>
            </h4>
            <button
              type="button"
              class="proj-details__add-toggle"
              @click="toggleProjectAddPanel(selectedProject.id)"
            >
              <span aria-hidden="true">{{
                isAddPanelOpen(selectedProject.id) ? "×" : "+"
              }}</span>
              {{ isAddPanelOpen(selectedProject.id) ? "Close" : "Add" }}
            </button>
          </div>

          <!-- Add panel -->
          <div
            v-if="isAddPanelOpen(selectedProject.id)"
            class="proj-details__add-form"
          >
            <input
              type="search"
              class="iz-input proj-details__add-form-input"
              :value="getAddPanelState(selectedProject.id).search"
              @input="
                getAddPanelState(selectedProject.id).search = $event.target.value
              "
              placeholder="Search org members…"
            />
            <div
              v-if="getAddPanelState(selectedProject.id).error"
              class="proj-details__add-form-error"
            >
              {{ getAddPanelState(selectedProject.id).error }}
            </div>
            <ul
              v-if="availableMembersForProject(selectedProject).length"
              class="proj-details__add-form-results"
            >
              <li
                v-for="u in availableMembersForProject(selectedProject)"
                :key="'avail-' + selectedProject.id + '-' + (u.userId || u.id)"
                class="proj-details__add-form-result"
              >
                <div class="proj-details__add-form-result-info">
                  <span class="proj-details__add-form-result-name">{{
                    u.displayName || u.userId || u.id
                  }}</span>
                  <span class="proj-details__add-form-result-meta">
                    <template v-if="u.email">{{ u.email }} · </template>uid: {{ u.userId || u.id }}
                  </span>
                </div>
                <select
                  :value="rowRoleFor(selectedProject.id, u.userId || u.id)"
                  class="iz-select proj-details__add-form-role"
                  :aria-label="
                    'DRASCI role for ' + (u.displayName || u.userId || u.id)
                  "
                  @change="
                    setRowRole(
                      selectedProject.id,
                      u.userId || u.id,
                      $event.target.value
                    )
                  "
                >
                  <option value="">DRASCI role…</option>
                  <option
                    v-for="opt in drasciOptions()"
                    :key="'r-' + opt.value"
                    :value="opt.value"
                  >
                    {{ opt.label }}
                  </option>
                </select>
                <button
                  type="button"
                  class="proj-details__add-form-add-btn"
                  :disabled="
                    getAddPanelState(selectedProject.id).addingUid !== null ||
                    !rowRoleFor(selectedProject.id, u.userId || u.id)
                  "
                  :title="
                    rowRoleFor(selectedProject.id, u.userId || u.id)
                      ? ''
                      : 'Choose a DRASCI role first'
                  "
                  :aria-label="'Add ' + (u.displayName || u.userId || u.id)"
                  @click="addProjectMember(selectedProject.id, u.userId || u.id)"
                >
                  <span
                    v-if="
                      getAddPanelState(selectedProject.id).addingUid ===
                      (u.userId || u.id)
                    "
                    class="proj-details__spinner"
                    aria-hidden="true"
                  ></span>
                  <span v-else aria-hidden="true">+</span>
                </button>
              </li>
            </ul>
            <div v-else class="proj-details__add-form-state">
              <template
                v-if="getAddPanelState(selectedProject.id).search.trim()"
              >No matches.</template>
              <template v-else
                >All organization members are already on this project.</template
              >
            </div>
          </div>

          <!-- Loading / error / empty -->
          <div
            v-if="projectMembersLoading[selectedProject.id]"
            class="proj-details__members-state"
          >Loading…</div>
          <div
            v-else-if="projectMembersError[selectedProject.id]"
            class="proj-details__members-state proj-details__members-state--error"
          >{{ projectMembersError[selectedProject.id] }}</div>

          <!-- Member list -->
          <ul
            v-else-if="hasMembers(selectedProject.id)"
            class="proj-details__members"
          >
            <li
              v-for="m in projectMembersById[selectedProject.id]"
              :key="'pm-' + selectedProject.id + '-' + m.userId"
              class="proj-details__member"
            >
              <span class="iz-identity__avatar iz-identity__avatar--sm iz-identity__avatar--soft proj-details__member-avatar">{{
                (m.displayName || m.userId).charAt(0).toUpperCase()
              }}</span>
              <div class="proj-details__member-info">
                <span class="proj-details__member-name">{{
                  m.displayName || m.userId
                }}</span>
                <a
                  v-if="m.email"
                  :href="'mailto:' + m.email"
                  class="proj-details__member-email"
                >{{ m.email }}</a>
                <span
                  v-else
                  class="proj-details__member-email proj-details__member-email--muted"
                >No email</span>
              </div>
              <template
                v-if="
                  editRoleState[selectedProject.id] &&
                  editRoleState[selectedProject.id].editingUid === m.userId
                "
              >
                <select
                  class="iz-select proj-details__member-drasci-select"
                  :value="m.drasciRole || ''"
                  :disabled="editRoleState[selectedProject.id].saving"
                  @change="
                    saveMemberRole(
                      selectedProject.id,
                      m.userId,
                      $event.target.value
                    )
                  "
                >
                  <option value="" disabled>Pick role…</option>
                  <option
                    v-for="opt in drasciOptions()"
                    :key="'er-' + opt.value"
                    :value="opt.value"
                  >
                    {{ opt.label }}
                  </option>
                </select>
                <button
                  type="button"
                  class="proj-details__member-drasci-cancel"
                  @click="cancelEditRole(selectedProject.id)"
                  aria-label="Cancel"
                >×</button>
                <span
                  v-if="editRoleState[selectedProject.id].error"
                  class="proj-details__member-error"
                >{{ editRoleState[selectedProject.id].error }}</span>
              </template>
              <span
                v-else
                class="proj-details__member-drasci"
                :class="
                  'proj-details__member-drasci--' + (m.drasciRole || 'unassigned')
                "
                role="button"
                tabindex="0"
                :title="'Click to change DRASCI role'"
                @click="beginEditRole(selectedProject.id, m.userId)"
                @keydown.enter.prevent="beginEditRole(selectedProject.id, m.userId)"
              >{{ m.drasciRoleLabel || drasciLabelFromRole(m.drasciRole) }}</span>
              <span
                class="proj-details__member-role"
                :class="
                  m.isOwner
                    ? 'proj-details__member-role--owner'
                    : 'proj-details__member-role--member'
                "
              >
                <span v-if="m.isOwner" aria-hidden="true">★</span>
                {{ m.isOwner ? "Owner" : "Member" }}
              </span>
            </li>
          </ul>
          <div v-else class="proj-details__members-state">
            No team members assigned to this project.
          </div>
        </div>
      </div>

      <!-- ── #1: Row 3 — Gantt Timeline ── -->
      <div v-if="selectedProject.timeline.length > 0" class="proj-details__row">
        <div class="proj-details__card proj-details__card--full">
          <h4 class="proj-details__card-title">Project Timeline</h4>
          <TimelineChart :timeline="selectedProject.timeline" />
        </div>
      </div>

      <!-- ── #6: Row 4 — Task Browser with summary strip + sorting ── -->
      <div class="proj-details__row">
        <div class="proj-details__card proj-details__card--full">
          <h4 class="proj-details__card-title">Task Browser</h4>

          <!-- Urgency summary strip -->
          <div class="proj-details__tb-summary">
            <button
              class="proj-details__tb-summary-pill proj-details__tb-summary-pill--danger"
              :class="{
                'proj-details__tb-summary-pill--active':
                  tbFilterDue === 'overdue',
              }"
              @click="toggleDueFilter('overdue')"
            >
              <span
                class="proj-details__tb-summary-dot proj-details__tb-summary-dot--danger"
              ></span>
              {{ dueCounts.overdue }} Overdue
            </button>
            <button
              class="proj-details__tb-summary-pill proj-details__tb-summary-pill--warning"
              :class="{
                'proj-details__tb-summary-pill--active':
                  tbFilterDue === 'today',
              }"
              @click="toggleDueFilter('today')"
            >
              <span
                class="proj-details__tb-summary-dot proj-details__tb-summary-dot--warning"
              ></span>
              {{ dueCounts.today }} Due Today
            </button>
            <button
              class="proj-details__tb-summary-pill proj-details__tb-summary-pill--success"
              :class="{
                'proj-details__tb-summary-pill--active':
                  tbFilterStatus === 'done',
              }"
              @click="toggleStatusFilter('done')"
            >
              <span
                class="proj-details__tb-summary-dot proj-details__tb-summary-dot--success"
              ></span>
              {{ statusCounts.done }} Done
            </button>
            <button
              class="proj-details__tb-summary-pill proj-details__tb-summary-pill--info"
              :class="{
                'proj-details__tb-summary-pill--active':
                  tbFilterStatus === 'open',
              }"
              @click="toggleStatusFilter('open')"
            >
              <span
                class="proj-details__tb-summary-dot proj-details__tb-summary-dot--info"
              ></span>
              {{ statusCounts.open }} Open
            </button>
            <button
              v-if="signatureCount"
              class="proj-details__tb-summary-pill proj-details__tb-summary-pill--sign"
              :class="{
                'proj-details__tb-summary-pill--active':
                  tbFilterStatus === 'tosign',
              }"
              @click="toggleStatusFilter('tosign')"
            >
              <span
                class="proj-details__tb-summary-dot proj-details__tb-summary-dot--sign"
              ></span>
              {{ signatureCount }} To sign
            </button>
          </div>

          <!-- Filters -->
          <div class="proj-details__tb-filters">
            <div class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Search</label>
              <input
                v-model="tbFilterName"
                type="text"
                class="iz-input proj-details__tb-input"
                placeholder="Task name…"
              />
            </div>
            <div class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Status</label>
              <select v-model="tbFilterStatus" class="iz-select proj-details__tb-select">
                <option value="">All</option>
                <option value="open">Open</option>
                <option value="done">Done</option>
                <option value="archived">Archived</option>
              </select>
            </div>
            <div class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Stack</label>
              <select v-model="tbFilterStack" class="iz-select proj-details__tb-select">
                <option value="">All</option>
                <option v-for="s in projectStacks" :key="s" :value="s">
                  {{ s }}
                </option>
              </select>
            </div>
            <div class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Label</label>
              <select v-model="tbFilterLabel" class="iz-select proj-details__tb-select">
                <option value="">All</option>
                <option v-for="l in projectLabels" :key="l" :value="l">
                  {{ l }}
                </option>
              </select>
            </div>
            <div v-if="showAssignees" class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Assignee</label>
              <select
                v-model="tbFilterAssignee"
                class="iz-select proj-details__tb-select"
              >
                <option value="">All</option>
                <option v-for="a in projectAssigneeNames" :key="a" :value="a">
                  {{ a }}
                </option>
              </select>
            </div>
            <div class="proj-details__tb-filter">
              <label class="proj-details__tb-label">Due</label>
              <select v-model="tbFilterDue" class="iz-select proj-details__tb-select">
                <option value="">All</option>
                <option value="overdue">Overdue</option>
                <option value="today">Today</option>
                <option value="tomorrow">Tomorrow</option>
                <option value="nextSevenDays">Next 7 Days</option>
                <option value="later">Later</option>
                <option value="nodue">No Due Date</option>
              </select>
            </div>
          </div>

          <!-- Date range filter (own row) -->
          <div class="proj-details__date-filter-row">
            <label class="proj-details__tb-label">Opened</label>
            <div
              class="proj-details__date-range"
              @click="showDateRangePicker = !showDateRangePicker"
            >
              <span class="proj-details__date-range-value">
                {{ tbFilterDateFrom || "Start" }}
              </span>
              <span class="proj-details__date-range-arrow">→</span>
              <span class="proj-details__date-range-value">
                {{ tbFilterDateTo || "End" }}
              </span>
              <button
                v-if="tbFilterDateFrom || tbFilterDateTo"
                class="proj-details__date-range-clear"
                title="Clear dates"
                @click.stop="
                  tbFilterDateFrom = '';
                  tbFilterDateTo = '';
                  showDateRangePicker = false;
                "
              >
                ✕
              </button>
            </div>
            <!-- Calendar dropdown (in-flow, expands naturally) -->
            <div
              v-if="showDateRangePicker"
              v-click-outside="closeDatePicker"
              class="proj-details__date-picker-dropdown"
            >
              <div class="proj-details__date-picker-months">
                <div class="proj-details__date-picker-month">
                  <div class="proj-details__date-picker-header">
                    <button
                      class="proj-details__date-picker-nav"
                      @click.stop="shiftCalendar(-1)"
                    >
                      ‹
                    </button>
                    <span class="proj-details__date-picker-title">{{
                      calendarMonthLabel(0)
                    }}</span>
                    <span></span>
                  </div>
                  <div class="proj-details__date-picker-grid">
                    <span
                      v-for="d in ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']"
                      :key="d"
                      class="proj-details__date-picker-dow"
                      >{{ d }}</span
                    >
                    <span
                      v-for="(cell, ci) in calendarCells(0)"
                      :key="'L' + ci"
                      :class="dateCellClass(cell)"
                      @click.stop="cell.date && pickDate(cell.date)"
                      >{{ cell.day }}</span
                    >
                  </div>
                </div>
                <div class="proj-details__date-picker-month">
                  <div class="proj-details__date-picker-header">
                    <span></span>
                    <span class="proj-details__date-picker-title">{{
                      calendarMonthLabel(1)
                    }}</span>
                    <button
                      class="proj-details__date-picker-nav"
                      @click.stop="shiftCalendar(1)"
                    >
                      ›
                    </button>
                  </div>
                  <div class="proj-details__date-picker-grid">
                    <span
                      v-for="d in ['Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa', 'Su']"
                      :key="d"
                      class="proj-details__date-picker-dow"
                      >{{ d }}</span
                    >
                    <span
                      v-for="(cell, ci) in calendarCells(1)"
                      :key="'R' + ci"
                      :class="dateCellClass(cell)"
                      @click.stop="cell.date && pickDate(cell.date)"
                      >{{ cell.day }}</span
                    >
                  </div>
                </div>
              </div>
              <div class="proj-details__date-picker-footer">
                <button
                  class="proj-details__date-picker-btn"
                  @click.stop="
                    tbFilterDateFrom = '';
                    tbFilterDateTo = '';
                    datePickStep = 'from';
                  "
                >
                  Clear
                </button>
                <button
                  class="proj-details__date-picker-btn proj-details__date-picker-btn--apply"
                  @click.stop="showDateRangePicker = false"
                >
                  Apply
                </button>
              </div>
            </div>
          </div>

          <!-- Count -->
          <div class="proj-details__tb-count">
            {{ browserRows.length }} of {{ browserTotal }} rows
          </div>

          <!-- Table with sortable headers -->
          <div class="proj-details__tb-table-wrap">
            <table class="proj-details__table proj-details__tb-table">
              <thead>
                <tr>
                  <th
                    class="proj-details__th-sort"
                    :class="{
                      'proj-details__th-sort--active': tbSortKey === 'title',
                    }"
                    @click="toggleSort('title')"
                  >
                    Task
                    <span class="proj-details__sort-arrow">{{
                      sortArrow("title")
                    }}</span>
                  </th>
                  <th>Stack</th>
                  <th
                    class="proj-details__th-sort"
                    :class="{
                      'proj-details__th-sort--active': tbSortKey === 'status',
                    }"
                    @click="toggleSort('status')"
                  >
                    Status
                    <span class="proj-details__sort-arrow">{{
                      sortArrow("status")
                    }}</span>
                  </th>
                  <th>Labels</th>
                  <th v-if="showAssignees">Assignees</th>
                  <th
                    class="proj-details__th-sort"
                    :class="{
                      'proj-details__th-sort--active': tbSortKey === 'due',
                    }"
                    @click="toggleSort('due')"
                  >
                    Due Date
                    <span class="proj-details__sort-arrow">{{
                      sortArrow("due")
                    }}</span>
                  </th>
                  <th
                    class="proj-details__th-sort"
                    :class="{
                      'proj-details__th-sort--active': tbSortKey === 'age',
                    }"
                    @click="toggleSort('age')"
                  >
                    Opened
                    <span class="proj-details__sort-arrow">{{
                      sortArrow("age")
                    }}</span>
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="browserRows.length === 0">
                  <td :colspan="showAssignees ? 7 : 6" class="proj-details__tb-empty">
                    No tasks match the current filters
                  </td>
                </tr>
                <tr
                  v-for="task in paginatedTasks"
                  :key="'tb-' + task.id"
                  :class="{
                    'proj-details__tb-row--sign': task.kind === 'signature',
                  }"
                >
                  <td class="proj-details__tb-cell-title">
                    <a
                      v-if="task.kind === 'signature'"
                      :href="task.signUrl"
                      class="proj-details__tb-sign-link"
                      :title="'Sent for signature by ' + task.requestedBy"
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        width="13"
                        height="13"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        stroke-width="2"
                        stroke-linecap="round"
                        stroke-linejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M12 19l7-7 3 3-7 7-3-3z" />
                        <path d="M18 13l-1.5-7.5L2 2l3.5 14.5L13 18l5-5z" />
                        <path d="M2 2l7.586 7.586" />
                      </svg>
                      {{ task.title }}
                    </a>
                    <template v-else>{{ task.title }}</template>
                  </td>
                  <td>
                    <span class="proj-details__tb-stack-badge">{{
                      task.stack
                    }}</span>
                  </td>
                  <td>
                    <span
                      class="proj-details__tb-status"
                      :class="'proj-details__tb-status--' + task.status"
                      >{{ task.statusLabel || task.status }}</span
                    >
                  </td>
                  <td>
                    <span
                      v-for="lbl in task.labels"
                      :key="lbl"
                      class="proj-details__tb-label-badge"
                      >{{ lbl }}</span
                    >
                    <span
                      v-if="task.labels.length === 0"
                      class="proj-details__tb-muted"
                      >&mdash;</span
                    >
                  </td>
                  <td v-if="showAssignees">
                    <span v-if="task.assignees.length">{{
                      task.assignees.join(", ")
                    }}</span>
                    <span v-else class="proj-details__tb-muted">&mdash;</span>
                  </td>
                  <td>
                    <span
                      v-if="task.due"
                      class="proj-details__tb-due"
                      :class="'proj-details__tb-due--' + task.dueBucket"
                      >{{ formatDate(task.due) }}</span
                    >
                    <span v-else class="proj-details__tb-muted">&mdash;</span>
                  </td>
                  <td>
                    <span
                      v-if="task.createdAt"
                      class="proj-details__tb-age"
                      :title="formatDate(task.createdAt)"
                    >
                      {{ taskAge(task.createdAt) }}
                    </span>
                    <span v-else class="proj-details__tb-muted">&mdash;</span>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <!-- Pagination -->
          <div v-if="totalPages > 1" class="proj-details__tb-pagination">
            <button
              class="proj-details__tb-page-btn"
              :disabled="tbPage <= 1"
              @click="tbPage--"
            >
              &lsaquo; Prev
            </button>
            <span class="proj-details__tb-page-info"
              >Page {{ tbPage }} of {{ totalPages }}</span
            >
            <button
              class="proj-details__tb-page-btn"
              :disabled="tbPage >= totalPages"
              @click="tbPage++"
            >
              Next &rsaquo;
            </button>
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script>
import DonutChart from "./DonutChart.vue";
import TimelineChart from "./TimelineChart.vue";
import ProjectMap from "./ProjectMap.vue";
import UpcomingEventsPanel from "./UpcomingEventsPanel.vue";
import axios from "@nextcloud/axios";
import { generateUrl } from "@nextcloud/router";

// projectcreatoraio uses plain app routes but its controllers still require
// the OCS-APIRequest header (see ProjectApiController.php).
const PCAIO_HEADERS = {
  "OCS-APIRequest": "true",
  Accept: "application/json",
  "Content-Type": "application/json",
};

const DRASCI_OPTIONS = [
  { value: "driver", label: "Driver" },
  { value: "responsible", label: "Responsible" },
  { value: "accountable", label: "Accountable" },
  { value: "supportive", label: "Supportive" },
  { value: "consulted", label: "Consulted" },
  { value: "informed", label: "Informed" },
];

export default {
  name: "ProjectDetailsPanel",
  components: { DonutChart, TimelineChart, ProjectMap, UpcomingEventsPanel },
  directives: {
    "click-outside": {
      bind: function (el, binding) {
        el.__clickOutsideHandler = function (e) {
          if (!el.contains(e.target)) {
            binding.value(e);
          }
        };
        document.addEventListener("pointerdown", el.__clickOutsideHandler);
      },
      unbind: function (el) {
        document.removeEventListener("pointerdown", el.__clickOutsideHandler);
        delete el.__clickOutsideHandler;
      },
    },
  },
  props: {
    projects: {
      type: Array,
      default: function () {
        return [];
      },
    },
    showTeamWorkload: {
      type: Boolean,
      default: true,
    },
    showAssignees: {
      type: Boolean,
      default: true,
    },
    orgMembers: {
      type: Array,
      default: function () {
        return [];
      },
    },
    upcomingEvents: {
      type: Array,
      default: function () {
        return [];
      },
    },
    projectSignatures: {
      type: Object,
      default: function () {
        return {};
      },
    },
  },
  data: function () {
    return {
      selectedProjectId: "",
      tabSearch: "",
      tabStatusFilter: "",
      tabTaskDueFilter: "",
      tabTaskStatusFilter: "",
      stackColors: [
        "#4A90D9",
        "#E67E5A",
        "#2E9E5A",
        "#8B5CF6",
        "#0EA5E9",
        "#F59E0B",
        "#EC4899",
        "#6B7280",
        "#10B981",
        "#EF4444",
      ],
      // Task browser
      tbFilterName: "",
      tbFilterStatus: "",
      tbFilterStack: "",
      tbFilterLabel: "",
      tbFilterAssignee: "",
      tbFilterDue: "",
      tbFilterDateFrom: "",
      tbFilterDateTo: "",
      showDateRangePicker: false,
      datePickStep: "from",
      calendarBase: new Date(),
      tbPage: 1,
      tbPageSize: 15,
      tbSortKey: "",
      tbSortDir: "asc",
      // Project team members (lazy per-project)
      projectMembersById: {},      // projectId → array of {userId, displayName, email, drasciRole, drasciRoleLabel, isOwner}
      projectMembersLoading: {},   // projectId → bool
      projectMembersError: {},     // projectId → string|null
      addPanelByProject: {},       // projectId → {open, search, rowRoles, addingUid, error}
      editRoleState: {},           // projectId → {editingUid, saving, error}
      // Project map (lazy per-project)
      geocodeByProject: {},        // projectId → { lat, lng, displayName, source, addrHash, fromCache }
      geocodeStatus: {},           // projectId → 'loading' | 'loaded' | 'no_address' | 'not_found' | 'unavailable'
      geocodeError: {},            // projectId → string|null
    };
  },
  mounted: function () {
    if (this.selectedProjectId) {
      this.ensureProjectMembersLoaded(this.selectedProjectId);
      this.fetchProjectGeocode(this.selectedProjectId);
    }
  },
  watch: {
    selectedProjectId: function (newId) {
      this.resetFilters();
      if (newId) {
        this.ensureProjectMembersLoaded(newId);
        this.fetchProjectGeocode(newId);
      }
    },
    tbFilterName: function () {
      this.tbPage = 1;
    },
    tbFilterStatus: function () {
      this.tbPage = 1;
    },
    tbFilterStack: function () {
      this.tbPage = 1;
    },
    tbFilterLabel: function () {
      this.tbPage = 1;
    },
    tbFilterAssignee: function () {
      this.tbPage = 1;
    },
    tbFilterDue: function () {
      this.tbPage = 1;
    },
    tbFilterDateFrom: function () {
      this.tbPage = 1;
    },
    tbFilterDateTo: function () {
      this.tbPage = 1;
    },
  },
  computed: {
    // Tab strip
    visibleProjects: function () {
      var self = this;
      var list = this.projects;
      if (this.tabStatusFilter) {
        list = list.filter(function (p) {
          return p.statusLabel === self.tabStatusFilter;
        });
      }
      if (this.tabTaskDueFilter) {
        var dueVal = this.tabTaskDueFilter;
        list = list.filter(function (p) {
          var tasks = p.tasks || [];
          for (var i = 0; i < tasks.length; i++) {
            if (tasks[i].dueBucket === dueVal) return true;
          }
          return false;
        });
      }
      if (this.tabTaskStatusFilter) {
        var statusVal = this.tabTaskStatusFilter;
        list = list.filter(function (p) {
          var tasks = p.tasks || [];
          for (var i = 0; i < tasks.length; i++) {
            if (tasks[i].status === statusVal) return true;
          }
          return false;
        });
      }
      if (this.tabSearch) {
        var q = this.tabSearch.toLowerCase();
        list = list.filter(function (p) {
          return (
            p.name.toLowerCase().indexOf(q) !== -1 ||
            (p.number && p.number.toLowerCase().indexOf(q) !== -1)
          );
        });
      }
      return list;
    },
    selectedProject: function () {
      if (!this.selectedProjectId) return null;
      var id = Number(this.selectedProjectId);
      return (
        this.projects.find(function (p) {
          return p.id === id;
        }) || null
      );
    },
    /* Meetings explicitly linked to this project, via the calendar fork's
       oc_calendar_project_events table (CalendarService attaches projectId).
       Nothing deployed writes that table yet, so this is empty in practice —
       see projectMeetings for what happens then. */
    linkedMeetings: function () {
      if (!this.selectedProject) return [];
      var pid = this.selectedProject.id;
      var out = [];
      for (var i = 0; i < this.upcomingEvents.length; i++) {
        if (this.upcomingEvents[i].projectId === pid) {
          out.push(this.upcomingEvents[i]);
        }
      }
      return out;
    },
    /* Fallback while the link table is unwritten: a project's meetings are the
       meetings of the people on it, i.e. every upcoming event whose calendar
       owner is in this project's member list. Members are fetched lazily on
       selection, so this stays empty until projectMembersById fills in. */
    teamMeetings: function () {
      if (!this.selectedProject) return [];
      var members = this.projectMembersById[this.selectedProject.id] || [];
      var uids = {};
      for (var i = 0; i < members.length; i++) {
        uids[members[i].userId] = true;
      }
      var out = [];
      for (var j = 0; j < this.upcomingEvents.length; j++) {
        if (uids[this.upcomingEvents[j].member]) {
          out.push(this.upcomingEvents[j]);
        }
      }
      return out;
    },
    projectMeetings: function () {
      var linked = this.linkedMeetings;
      return linked.length ? linked : this.teamMeetings;
    },
    hasClientInfo: function () {
      if (!this.selectedProject) return false;
      var p = this.selectedProject;
      return !!(
        p.clientName ||
        p.clientEmail ||
        p.clientPhone ||
        (p.location && p.location !== ",")
      );
    },
    // Stack donut — build single chartData object
    stackChartData: function () {
      if (!this.selectedProject) return { labels: [], data: [], colors: [] };
      var self = this;
      var filtered = this.selectedProject.tasksByStack.filter(function (s) {
        return s.total > 0;
      });
      return {
        labels: filtered.map(function (s) {
          return s.stack;
        }),
        data: filtered.map(function (s) {
          return s.total;
        }),
        colors: filtered.map(function (_, i) {
          return self.stackColors[i % self.stackColors.length];
        }),
      };
    },
    // Task browser
    projectTasks: function () {
      if (!this.selectedProject) return [];
      return this.selectedProject.tasks || [];
    },
    /* Documents waiting on the viewer's signature in this project, shaped as
       Task Browser rows so they can share the table. Gated on showAssignees:
       a public share link must not reveal who still owes a signature. */
    projectSignatureRows: function () {
      if (!this.selectedProject || !this.showAssignees) return [];
      var list = this.projectSignatures[this.selectedProject.id] || [];
      return list.map(function (s) {
        return {
          id: "sig-" + s.signUuid,
          kind: "signature",
          title: s.fileName,
          stack: "Signatures",
          status: "tosign",
          statusLabel: "to sign",
          labels: s.signatureFlow
            ? ["Signature", s.signatureFlow]
            : ["Signature"],
          assignees: s.signerName ? [s.signerName] : [],
          due: null,
          dueBucket: "nodue",
          createdAt: s.requestedAt,
          requestedBy: s.requestedBy,
          // "signatures", not "libresign": this stack ships LibreSign
          // rebranded, so the app id differs from the oc_libresign_* tables.
          signUrl: generateUrl("/apps/signatures/p/sign/" + s.signUuid),
        };
      });
    },
    signatureCount: function () {
      return this.projectSignatureRows.length;
    },
    filteredSignatures: function () {
      var self = this;
      // A signature has no Deck stack, no status but "to sign" and no due
      // date, so a filter on any of those three excludes the whole set.
      if (this.tbFilterStatus && this.tbFilterStatus !== "tosign") return [];
      if (this.tbFilterStack && this.tbFilterStack !== "Signatures") return [];
      if (this.tbFilterDue && this.tbFilterDue !== "nodue") return [];
      return this.projectSignatureRows.filter(function (r) {
        if (
          self.tbFilterName &&
          r.title.toLowerCase().indexOf(self.tbFilterName.toLowerCase()) === -1
        )
          return false;
        if (self.tbFilterLabel && r.labels.indexOf(self.tbFilterLabel) === -1)
          return false;
        if (
          self.tbFilterAssignee &&
          r.assignees.indexOf(self.tbFilterAssignee) === -1
        )
          return false;
        if (self.tbFilterDateFrom || self.tbFilterDateTo) {
          if (!r.createdAt) return false;
          var d = String(r.createdAt).substring(0, 10);
          if (self.tbFilterDateFrom && d < self.tbFilterDateFrom) return false;
          if (self.tbFilterDateTo && d > self.tbFilterDateTo) return false;
        }
        return true;
      });
    },
    /* Signatures pinned above the cards whatever the sort: having no due date
       they would otherwise sink to the bottom under the default Due sort,
       which is the opposite of the point of showing them here. */
    browserRows: function () {
      return this.filteredSignatures.concat(this.sortedTasks);
    },
    browserTotal: function () {
      return this.projectTasks.length + this.signatureCount;
    },
    projectStacks: function () {
      if (!this.selectedProject) return [];
      return this.selectedProject.taskStacks || [];
    },
    projectLabels: function () {
      if (!this.selectedProject) return [];
      return this.selectedProject.taskLabels || [];
    },
    // Unique assignee names for the filter dropdown
    projectAssigneeNames: function () {
      var names = {};
      this.projectTasks.forEach(function (t) {
        (t.assignees || []).forEach(function (a) {
          names[a] = true;
        });
      });
      return Object.keys(names).sort();
    },
    // Per-project Timeline KPIs
    coordinationPending: function () {
      if (!this.selectedProject) return "—";
      var tl = this.selectedProject.timeline || [];
      var item = null;
      for (var i = 0; i < tl.length; i++) {
        if (tl[i].systemKey === "request_date") {
          item = tl[i];
          break;
        }
      }
      if (!item || !item.startDate) return "—";
      var start = new Date(item.startDate);
      if (isNaN(start.getTime())) return "—";
      var now = new Date();
      var days = Math.floor(
        (now.getTime() - start.getTime()) / (1000 * 60 * 60 * 24),
      );
      var weeks = Math.round(days / 7);
      return weeks + " wk" + (weeks !== 1 ? "s" : "");
    },
    requiredPrepTime: function () {
      if (!this.selectedProject) return "—";
      var tl = this.selectedProject.timeline || [];
      var item = null;
      for (var i = 0; i < tl.length; i++) {
        if (tl[i].systemKey === "required_preparation") {
          item = tl[i];
          break;
        }
      }
      if (!item || !item.startDate || !item.endDate) return "—";
      var s = new Date(item.startDate);
      var e = new Date(item.endDate);
      if (isNaN(s.getTime()) || isNaN(e.getTime())) return "—";
      var days = Math.floor(
        (e.getTime() - s.getTime()) / (1000 * 60 * 60 * 24),
      );
      var weeks = Math.round(days / 7);
      return weeks + " wk" + (weeks !== 1 ? "s" : "");
    },
    // Summary counts for the urgency strip
    dueCounts: function () {
      var counts = { overdue: 0, today: 0 };
      this.projectTasks.forEach(function (t) {
        if (t.dueBucket === "overdue") counts.overdue++;
        if (t.dueBucket === "today") counts.today++;
      });
      return counts;
    },
    statusCounts: function () {
      var counts = { open: 0, done: 0 };
      this.projectTasks.forEach(function (t) {
        if (t.status === "open") counts.open++;
        if (t.status === "done") counts.done++;
      });
      return counts;
    },
    filteredTasks: function () {
      var self = this;
      return this.projectTasks.filter(function (t) {
        if (
          self.tbFilterName &&
          t.title.toLowerCase().indexOf(self.tbFilterName.toLowerCase()) === -1
        )
          return false;
        if (self.tbFilterStatus && t.status !== self.tbFilterStatus)
          return false;
        if (self.tbFilterStack && t.stack !== self.tbFilterStack) return false;
        if (self.tbFilterLabel && t.labels.indexOf(self.tbFilterLabel) === -1)
          return false;
        if (
          self.tbFilterAssignee &&
          (t.assignees || []).indexOf(self.tbFilterAssignee) === -1
        )
          return false;
        if (self.tbFilterDue && t.dueBucket !== self.tbFilterDue) return false;
        if (self.tbFilterDateFrom || self.tbFilterDateTo) {
          if (!t.createdAt) return false;
          var taskDate = t.createdAt.substring(0, 10);
          if (self.tbFilterDateFrom && taskDate < self.tbFilterDateFrom)
            return false;
          if (self.tbFilterDateTo && taskDate > self.tbFilterDateTo)
            return false;
        }
        return true;
      });
    },
    sortedTasks: function () {
      if (!this.tbSortKey) return this.filteredTasks;
      var key = this.tbSortKey;
      var dir = this.tbSortDir === "asc" ? 1 : -1;
      var arr = this.filteredTasks.slice();
      arr.sort(function (a, b) {
        var va, vb;
        if (key === "title") {
          va = (a.title || "").toLowerCase();
          vb = (b.title || "").toLowerCase();
        } else if (key === "status") {
          var order = { open: 1, done: 2, archived: 3 };
          va = order[a.status] || 4;
          vb = order[b.status] || 4;
        } else if (key === "due") {
          va = a.due ? new Date(a.due).getTime() : 9999999999999;
          vb = b.due ? new Date(b.due).getTime() : 9999999999999;
        } else if (key === "age") {
          va = a.createdAt ? new Date(a.createdAt).getTime() : 9999999999999;
          vb = b.createdAt ? new Date(b.createdAt).getTime() : 9999999999999;
        }
        if (va < vb) return -1 * dir;
        if (va > vb) return 1 * dir;
        return 0;
      });
      return arr;
    },
    totalPages: function () {
      return Math.max(1, Math.ceil(this.browserRows.length / this.tbPageSize));
    },
    paginatedTasks: function () {
      var start = (this.tbPage - 1) * this.tbPageSize;
      return this.browserRows.slice(start, start + this.tbPageSize);
    },
  },
  methods: {
    resetFilters: function () {
      this.tbFilterName = "";
      this.tbFilterStatus = "";
      this.tbFilterStack = "";
      this.tbFilterLabel = "";
      this.tbFilterAssignee = "";
      this.tbFilterDue = "";
      this.tbFilterDateFrom = "";
      this.tbFilterDateTo = "";
      this.showDateRangePicker = false;
      this.datePickStep = "from";
      this.tbPage = 1;
      this.tbSortKey = "";
      this.tbSortDir = "asc";
    },
    /* ---- Date range picker helpers ---- */
    pad: function (n) {
      return n < 10 ? "0" + n : "" + n;
    },
    toDateStr: function (d) {
      return (
        d.getFullYear() +
        "-" +
        this.pad(d.getMonth() + 1) +
        "-" +
        this.pad(d.getDate())
      );
    },
    calendarMonthLabel: function (offset) {
      var d = new Date(
        this.calendarBase.getFullYear(),
        this.calendarBase.getMonth() + offset,
        1,
      );
      var months = [
        "January",
        "February",
        "March",
        "April",
        "May",
        "June",
        "July",
        "August",
        "September",
        "October",
        "November",
        "December",
      ];
      return months[d.getMonth()] + " " + d.getFullYear();
    },
    shiftCalendar: function (dir) {
      var d = new Date(this.calendarBase);
      d.setMonth(d.getMonth() + dir);
      this.calendarBase = d;
    },
    calendarCells: function (offset) {
      var year = this.calendarBase.getFullYear();
      var month = this.calendarBase.getMonth() + offset;
      var first = new Date(year, month, 1);
      var dayOfWeek = first.getDay(); // 0=Sun
      var startPad = dayOfWeek === 0 ? 6 : dayOfWeek - 1; // Mon-based
      var daysInMonth = new Date(year, month + 1, 0).getDate();
      var cells = [];
      for (var i = 0; i < startPad; i++) {
        cells.push({ day: "", date: null });
      }
      for (var d = 1; d <= daysInMonth; d++) {
        cells.push({ day: d, date: this.toDateStr(new Date(year, month, d)) });
      }
      return cells;
    },
    pickDate: function (dateStr) {
      if (this.datePickStep === "from") {
        this.tbFilterDateFrom = dateStr;
        this.tbFilterDateTo = "";
        this.datePickStep = "to";
      } else {
        if (dateStr < this.tbFilterDateFrom) {
          this.tbFilterDateFrom = dateStr;
          this.tbFilterDateTo = "";
          this.datePickStep = "to";
        } else {
          this.tbFilterDateTo = dateStr;
          this.datePickStep = "from";
        }
      }
    },
    dateCellClass: function (cell) {
      var cls = ["proj-details__date-picker-cell"];
      if (!cell.date) {
        cls.push("proj-details__date-picker-cell--empty");
        return cls;
      }
      var from = this.tbFilterDateFrom;
      var to = this.tbFilterDateTo;
      if (cell.date === from) cls.push("proj-details__date-picker-cell--start");
      if (cell.date === to) cls.push("proj-details__date-picker-cell--end");
      if (from && to && cell.date > from && cell.date < to)
        cls.push("proj-details__date-picker-cell--in-range");
      if (cell.date === from && !to)
        cls.push("proj-details__date-picker-cell--solo");
      var today = this.toDateStr(new Date());
      if (cell.date === today)
        cls.push("proj-details__date-picker-cell--today");
      return cls;
    },
    closeDatePicker: function () {
      this.showDateRangePicker = false;
    },
    assigneePct: function (a) {
      if (!a.tasks || a.tasks === 0) return 0;
      return Math.round(((a.doneTasks || 0) / a.tasks) * 100);
    },
    toggleSort: function (key) {
      if (this.tbSortKey === key) {
        this.tbSortDir = this.tbSortDir === "asc" ? "desc" : "asc";
      } else {
        this.tbSortKey = key;
        this.tbSortDir = "asc";
      }
      this.tbPage = 1;
    },
    sortArrow: function (key) {
      if (this.tbSortKey !== key) return "↕";
      return this.tbSortDir === "asc" ? "↑" : "↓";
    },
    toggleDueFilter: function (val) {
      this.tbFilterDue = this.tbFilterDue === val ? "" : val;
    },
    toggleStatusFilter: function (val) {
      this.tbFilterStatus = this.tbFilterStatus === val ? "" : val;
    },
    clearProjectFilters: function () {
      this.tabSearch = "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
    },
    taskAge: function (createdAt) {
      if (!createdAt) return "—";
      var created = new Date(createdAt);
      if (isNaN(created.getTime())) return "—";
      var now = new Date();
      var diffMs = now.getTime() - created.getTime();
      var days = Math.floor(diffMs / (1000 * 60 * 60 * 24));
      if (days < 1) return "Today";
      if (days === 1) return "1 day";
      if (days < 7) return days + " days";
      var weeks = Math.floor(days / 7);
      if (weeks < 5) return weeks + (weeks === 1 ? " week" : " weeks");
      var months = Math.floor(days / 30);
      if (months < 12) return months + (months === 1 ? " month" : " months");
      var years = Math.floor(days / 365);
      return years + (years === 1 ? " year" : " years");
    },
    applyProjectFilter: function (statusLabel) {
      // Deselect current project so user sees filtered list
      this.selectedProjectId = "";
      // Clear all existing filters
      this.tabSearch = "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
      // Set the matching project status filter
      this.tabStatusFilter = statusLabel;
      var self = this;
      this.$nextTick(function () {
        var el = self.$el;
        if (el) {
          el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    },
    applyTaskFilter: function (filterType, filterValue) {
      // Deselect current project so user sees filtered list
      this.selectedProjectId = "";
      // Clear existing project filters
      this.tabSearch = "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
      // Set the matching tab-level filter
      if (filterType === "due") {
        this.tabTaskDueFilter = filterValue;
      } else if (filterType === "status") {
        this.tabTaskStatusFilter = filterValue;
      }
      // Scroll to the project selector
      var self = this;
      this.$nextTick(function () {
        var el = self.$el;
        if (el) {
          el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    },
    selectProject: function (boardId, projectName) {
      // Find the project by name (progressDetails uses board_id, projectDetails uses custom id)
      var match = this.projects.find(function (p) {
        return p.name === projectName;
      });
      // Clear filters and select
      this.tabSearch = projectName || "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
      this.selectedProjectId = match ? match.id : "";
      var self = this;
      this.$nextTick(function () {
        self.$el.scrollIntoView({ behavior: "smooth", block: "start" });
      });
    },
    selectProjectAndFilterTask: function (projectId, taskTitle) {
      // Find the project name for the search field
      var match = this.projects.find(function (p) {
        return p.id === projectId || String(p.id) === String(projectId);
      });
      // Clear all tab-level filters
      this.tabSearch = match ? match.name : "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
      // Select the project
      this.selectedProjectId = projectId;
      // Set the task name filter in the task browser
      var self = this;
      this.$nextTick(function () {
        self.resetFilters();
        self.tbFilterName = taskTitle;
        self.$nextTick(function () {
          var tbEl = self.$el.querySelector(".proj-details__tb-table-wrap");
          if (tbEl) {
            tbEl.scrollIntoView({ behavior: "smooth", block: "start" });
          }
        });
      });
    },
    formatDate: function (d) {
      if (!d) return "—";
      var date = new Date(d);
      if (isNaN(date.getTime())) return d;
      return date.toLocaleDateString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
      });
    },
    drasciOptions: function () {
      return DRASCI_OPTIONS;
    },
    drasciLabelFromRole: function (role) {
      if (!role) return "Unassigned";
      for (var i = 0; i < DRASCI_OPTIONS.length; i++) {
        if (DRASCI_OPTIONS[i].value === role) return DRASCI_OPTIONS[i].label;
      }
      return "Unassigned";
    },
    hasMembers: function (projectId) {
      var list = this.projectMembersById[projectId];
      return !!list && list.length > 0;
    },
    projectMemberCount: function (projectId) {
      var list = this.projectMembersById[projectId];
      return list ? list.length : 0;
    },
    isAddPanelOpen: function (projectId) {
      var s = this.addPanelByProject[projectId];
      return !!(s && s.open);
    },
    getAddPanelState: function (projectId) {
      if (!this.addPanelByProject[projectId]) {
        this.$set(this.addPanelByProject, projectId, {
          open: false,
          search: "",
          rowRoles: {},
          addingUid: null,
          error: null,
        });
      }
      return this.addPanelByProject[projectId];
    },
    toggleProjectAddPanel: function (projectId) {
      var s = this.getAddPanelState(projectId);
      if (s.open) {
        this.closeProjectAddPanel(projectId);
      } else {
        s.open = true;
        s.search = "";
        s.rowRoles = {};
        s.error = null;
      }
    },
    closeProjectAddPanel: function (projectId) {
      var s = this.getAddPanelState(projectId);
      s.open = false;
      s.search = "";
      s.rowRoles = {};
      s.error = null;
    },
    setRowRole: function (projectId, uid, role) {
      var s = this.getAddPanelState(projectId);
      this.$set(s.rowRoles, uid, role);
    },
    rowRoleFor: function (projectId, uid) {
      var s = this.addPanelByProject[projectId];
      return (s && s.rowRoles && s.rowRoles[uid]) || "";
    },
    availableMembersForProject: function (project) {
      var existing = {};
      var existingList = this.projectMembersById[project.id] || [];
      for (var i = 0; i < existingList.length; i++) {
        var m = existingList[i];
        var uid = m.userId || m.id;
        if (uid) existing[uid] = true;
      }
      var state = this.addPanelByProject[project.id];
      var q = state ? (state.search || "").trim().toLowerCase() : "";
      var out = [];
      var src = this.orgMembers || [];
      for (var j = 0; j < src.length; j++) {
        var om = src[j];
        var omUid = om.userId || om.id;
        if (!omUid || existing[omUid]) continue;
        if (q) {
          var name = (om.displayName || "").toLowerCase();
          var omU = (omUid || "").toLowerCase();
          var email = (om.email || "").toLowerCase();
          if (
            name.indexOf(q) === -1 &&
            omU.indexOf(q) === -1 &&
            email.indexOf(q) === -1
          ) {
            continue;
          }
        }
        out.push(om);
      }
      out.sort(function (a, b) {
        var an = (a.displayName || a.userId || a.id || "").toLowerCase();
        var bn = (b.displayName || b.userId || b.id || "").toLowerCase();
        if (an < bn) return -1;
        if (an > bn) return 1;
        return 0;
      });
      return out;
    },
    ensureProjectMembersLoaded: function (projectId) {
      if (!projectId) return;
      if (this.projectMembersLoading[projectId]) return;
      if (this.projectMembersById[projectId]) return; // already loaded
      this.fetchProjectMembers(projectId);
    },
    fetchProjectMembers: async function (projectId) {
      if (!projectId) return;
      this.$set(this.projectMembersLoading, projectId, true);
      this.$set(this.projectMembersError, projectId, null);
      try {
        const res = await axios.get(
          generateUrl(
            "/apps/projectcreatoraio/api/v1/projects/" + projectId + "/members"
          ),
          { headers: PCAIO_HEADERS }
        );
        const list = (res.data && res.data.members) || [];
        const norm = [];
        for (var i = 0; i < list.length; i++) {
          var m = list[i];
          norm.push({
            userId: m.userId || m.id || "",
            displayName: m.displayName || m.userId || m.id || "",
            email: m.email || "",
            drasciRole: m.drasciRole || "",
            drasciRoleLabel: m.drasciRoleLabel || "",
            isOwner: !!m.isOwner,
          });
        }
        this.$set(this.projectMembersById, projectId, norm);
      } catch (e) {
        this.$set(
          this.projectMembersError,
          projectId,
          this.extractProjectMembersError(e, "Couldn't load team members.")
        );
      } finally {
        this.$set(this.projectMembersLoading, projectId, false);
      }
    },
    addProjectMember: async function (projectId, uid) {
      var s = this.getAddPanelState(projectId);
      if (s.addingUid !== null) return;
      var role = (s.rowRoles && s.rowRoles[uid]) || "";
      if (!role) {
        s.error = "Choose a DRASCI role before adding.";
        return;
      }
      s.addingUid = uid;
      s.error = null;
      try {
        await axios.post(
          generateUrl(
            "/apps/projectcreatoraio/api/v1/projects/" + projectId + "/members"
          ),
          { userId: uid, drasciRole: role },
          { headers: PCAIO_HEADERS }
        );
        this.closeProjectAddPanel(projectId);
        this.$delete(this.projectMembersById, projectId);
        await this.fetchProjectMembers(projectId);
      } catch (e) {
        s.error = this.extractProjectMembersError(
          e,
          "Couldn't add team member."
        );
      } finally {
        s.addingUid = null;
      }
    },
    beginEditRole: function (projectId, uid) {
      this.$set(this.editRoleState, projectId, {
        editingUid: uid,
        saving: false,
        error: null,
      });
    },
    cancelEditRole: function (projectId) {
      this.$set(this.editRoleState, projectId, {
        editingUid: null,
        saving: false,
        error: null,
      });
    },
    saveMemberRole: async function (projectId, uid, role) {
      var st = this.editRoleState[projectId] || {};
      if (!role || st.saving) return;
      this.$set(this.editRoleState, projectId, {
        editingUid: uid,
        saving: true,
        error: null,
      });
      try {
        await axios.put(
          generateUrl(
            "/apps/projectcreatoraio/api/v1/projects/" +
              projectId +
              "/members/" +
              encodeURIComponent(uid) +
              "/role"
          ),
          { drasciRole: role },
          { headers: PCAIO_HEADERS }
        );
        this.$set(this.editRoleState, projectId, {
          editingUid: null,
          saving: false,
          error: null,
        });
        this.$delete(this.projectMembersById, projectId);
        await this.fetchProjectMembers(projectId);
      } catch (e) {
        this.$set(this.editRoleState, projectId, {
          editingUid: uid,
          saving: false,
          error: this.extractProjectMembersError(
            e,
            "Couldn't update role."
          ),
        });
      }
    },
    extractProjectMembersError: function (err, fallback) {
      if (!err) return fallback;
      if (!err.response) return "Couldn't reach the server. Try again.";
      var status = err.response.status;
      if (status === 403) return "No access to this project.";
      if (status === 404) return "Project no longer exists.";
      if (status === 400) return "Invalid request.";
      if (status >= 500) return "Server error. Try again.";
      var ocsMsg =
        err.response.data &&
        err.response.data.ocs &&
        err.response.data.ocs.meta &&
        err.response.data.ocs.meta.message;
      if (ocsMsg) return ocsMsg;
      return fallback + " (HTTP " + status + ")";
    },
    fetchProjectGeocode: async function (projectId) {
      if (!projectId) return;
      if (this.geocodeStatus[projectId] === 'loading') return;
      this.$set(this.geocodeStatus, projectId, 'loading');
      this.$set(this.geocodeError, projectId, null);
      try {
        const res = await axios.get(
          generateUrl(
            "/apps/adminpage/api/projects/" + projectId + "/geocode"
          )
        );
        const d = (res && res.data) || {};
        if (d.lat != null && d.lng != null) {
          this.$set(this.geocodeByProject, projectId, d);
          this.$set(this.geocodeStatus, projectId, 'loaded');
        } else {
          this.$set(this.geocodeStatus, projectId, 'not_found');
        }
      } catch (e) {
        const code = (e && e.response && e.response.status) || 0;
        const reason = (e && e.response && e.response.data && e.response.data.reason) || '';
        if (code === 404 && reason === 'no_address') {
          this.$set(this.geocodeStatus, projectId, 'no_address');
        } else if (code === 404 && reason === 'not_found') {
          this.$set(this.geocodeStatus, projectId, 'not_found');
        } else if (code === 503) {
          this.$set(this.geocodeStatus, projectId, 'unavailable');
          this.$set(this.geocodeError, projectId, "Geocoding service unavailable.");
        } else {
          this.$set(this.geocodeStatus, projectId, 'unavailable');
          this.$set(this.geocodeError, projectId, "Couldn't load map.");
        }
      }
    },
    setSelectedProject: function (projectId) {
      if (projectId == null) return;
      // Mirror the existing selectProject(name) flow used by "Details" buttons
      // elsewhere in the dashboard: clear tab filters that could hide the
      // newly-selected project from the tab strip, set the id, then scroll
      // THIS panel into view (not the perf panel wrapper, which leaves details
      // below the fold).
      var match = this.projects.find(function (p) {
        return p.id === projectId || String(p.id) === String(projectId);
      });
      this.tabSearch = match ? match.name : "";
      this.tabStatusFilter = "";
      this.tabTaskDueFilter = "";
      this.tabTaskStatusFilter = "";
      this.selectedProjectId = match ? match.id : String(projectId);
      var self = this;
      this.$nextTick(function () {
        if (self.$el && self.$el.scrollIntoView) {
          self.$el.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
    },
  },
};
</script>

<style scoped>
