  width: 200px;
}


/* Chrome from .iz-select. width:auto because the primitive is width:100% —
   right for a stacked form, wrong for these sitting in a toolbar row. */
.proj-details__tabs-status-select {
  width: auto;
  cursor: pointer;
}

.proj-details__tabs-status-select:focus {
  border-color: var(--accent);
}

.proj-details__tabs-clear {
  padding: 5px 12px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 8px;
  background: var(--bg-card);
  font-size: 12px;
  font-weight: 500;
  color: var(--color-text-muted, #9ca3af);
  cursor: pointer;
  transition: all 0.15s;
}

.proj-details__tabs-clear:hover {
  background: var(--color-badge-danger-bg);
  border-color: var(--color-danger);
  color: var(--color-danger);
}

.proj-details__tabs-strip {
  display: flex;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 4px;
  scrollbar-width: thin;
}

.proj-details__tabs-strip::-webkit-scrollbar {
  height: 4px;
}

.proj-details__tabs-strip::-webkit-scrollbar-thumb {
  background: var(--color-border-strong);
  border-radius: 2px;
}

.proj-details__tab {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 20px;
  background: var(--bg-card);
  font-size: 12px;
  font-weight: 500;
  color: var(--color-text-primary, #1a1a2e);
  cursor: pointer;
  white-space: nowrap;
  flex-shrink: 0;
  transition: all 0.15s;
}

.proj-details__tab:hover {
  background: var(--bg-subtle);
  border-color: var(--accent);
}

.proj-details__tab--active {
  background: linear-gradient(135deg, var(--accent), var(--accent));
  color: #fff;
  border-color: var(--accent);
}

.proj-details__tab-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.proj-details__tab--active .proj-details__tab-dot {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.4);
}

.proj-details__tab-dot--active {
  background: var(--color-success);
}
.proj-details__tab-dot--waiting-on-customer {
  background: var(--chart-4);
}
.proj-details__tab-dot--on-hold {
  background: var(--color-danger);
}
.proj-details__tab-dot--done {
  background: var(--accent);
}

.proj-details__tab-name {
  max-width: 140px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.proj-details__tab-num {
  font-size: 10px;
  opacity: 0.7;
}

.proj-details__tabs-empty {
  font-size: 13px;
  color: var(--color-text-muted, #9ca3af);
  padding: 8px 0;
}

/* ── Empty State ── */
/* Box, border, padding and type come from .iz-empty; only layout is local. */
.proj-details__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 48px 24px;
}

.proj-details__empty-icon {
  margin-bottom: 12px;
  opacity: 0.4;
}
.proj-details__empty-text {
  font-size: 13px;
  margin: 0;
}

/* ── Layout ── */
.proj-details__row {
  margin-bottom: 16px;
}

.proj-details__row--two {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.proj-details__row--three {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
}

.proj-details__card {
  background: var(--bg-card, #fff);
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 10px;
  padding: 20px;
}

.proj-details__card--full {
  width: 100%;
}

.proj-details__card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
}

.proj-details__card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--color-text-primary, #1a1a2e);
  margin: 0 0 16px 0;
  padding: 0;
  border: none;
}

.proj-details__card-header .proj-details__card-title {
  margin-bottom: 0;
}

.proj-details__card-title--sub {
  font-size: 13px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border, #e5e7eb);
}

/* ── Badges ── */
.proj-details__badge {
  display: inline-block;
  padding: 3px 10px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.4;
}

.proj-details__badge--active {
  background: var(--color-badge-success-bg);
  color: var(--color-badge-success-text);
}
.proj-details__badge--waiting-on-customer {
  background: var(--color-badge-warning-bg);
  color: var(--color-badge-warning-text);
}
.proj-details__badge--on-hold {
  background: var(--color-badge-danger-bg);
  color: var(--color-badge-danger-text);
}
.proj-details__badge--done {
  background: var(--accent-bg);
  color: var(--accent-on-bg);
}

/* ── Info Grid ── */
.proj-details__info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.proj-details__info-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.proj-details__info-label {
  font-size: 11px;
  color: var(--color-text-muted, #9ca3af);
  font-weight: 500;
}

.proj-details__info-value {
  font-size: 13px;
  color: var(--color-text-primary, #1a1a2e);
  word-break: break-word;
}

.proj-details__info-value--multiline {
  white-space: pre-line;
}

.proj-details__info-link {
  font-size: 13px;
  color: var(--accent);
  text-decoration: none;
  word-break: break-word;
}

.proj-details__info-link:hover {
  text-decoration: underline;
}

.proj-details__no-client {
  font-size: 13px;
  color: var(--color-text-muted, #9ca3af);
  padding: 12px 0;
}

/* ── Progress ── */
.proj-details__progress {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--color-border, #e5e7eb);
}

.proj-details__progress-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.proj-details__progress-label {
  font-size: 12px;
  color: var(--color-text-secondary, #6b7280);
  font-weight: 500;
}

.proj-details__progress-pct {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__progress-bar {
  height: 8px;
  background: var(--bg-subtle);
  border-radius: 4px;
  overflow: hidden;
}

.proj-details__progress-fill {
  height: 100%;
  border-radius: 4px;
  transition: width 0.5s ease;
}

.proj-details__progress-fill--low {
  background: var(--color-danger);
}
.proj-details__progress-fill--mid {
  background: var(--chart-4);
}
.proj-details__progress-fill--high {
  background: var(--color-success);
}

.proj-details__progress-detail {
  font-size: 11px;
  color: var(--color-text-muted, #9ca3af);
  margin-top: 4px;
  display: block;
}

/* ── Resources ── */
.proj-details__resources {
  display: flex;
  gap: 0;
}

.proj-details__resource-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 12px 8px;
  border-radius: 8px;
  background: var(--bg-subtle);
}

.proj-details__resource-item + .proj-details__resource-item {
  margin-left: 8px;
}

.proj-details__resource-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__resource-label {
  font-size: 11px;
  color: var(--color-text-muted, #9ca3af);
  margin-top: 2px;
}

/* ── Chart ── */
.proj-details__chart-wrap {
  max-width: 200px;
  margin: 0 auto 8px;
}

.proj-details__no-data {
  text-align: center;
  font-size: 13px;
  color: var(--color-text-muted, #9ca3af);
  padding: 24px;
}

/* ── Due Grid ── */
.proj-details__due-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.proj-details__due-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 14px 10px;
  border-radius: 8px;
}

.proj-details__due-item--danger {
  background: var(--color-badge-danger-bg);
}
.proj-details__due-item--warning {
  background: var(--color-badge-warning-bg);
}
.proj-details__due-item--info {
  background: var(--accent-bg);
}
.proj-details__due-item--muted {
  background: var(--bg-subtle);
}

.proj-details__due-item--pulse {
  border: 2px solid var(--color-danger);
  animation: pulse-border 2s ease-in-out infinite;
}

@keyframes pulse-border {
  0%,
  100% {
    border-color: var(--color-danger);
  }
  50% {
    border-color: var(--color-badge-danger-bg);
  }
}

.proj-details__due-value {
  font-size: 22px;
  font-weight: 700;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__due-label {
  font-size: 11px;
  color: var(--color-text-muted, #9ca3af);
  margin-top: 2px;
}

/* ── #2: Team Workload ── */
.proj-details__team-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.proj-details__team-member {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.proj-details__team-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.proj-details__team-info {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
}

/* Chrome from .iz-identity__avatar--sm; the circle is local — these read as
   people in a row rather than as cards, and the rounded square does not. */
.proj-details__team-avatar {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  font-size: 11px;
}

.proj-details__team-name {
  font-size: 13px;
  color: var(--color-text-primary, #1a1a2e);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.proj-details__team-stats {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.proj-details__team-count {
  font-size: 11px;
  color: var(--color-text-muted, #9ca3af);
}

.proj-details__team-pct {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__team-bar {
  height: 4px;
  background: var(--bg-subtle);
  border-radius: 2px;
  overflow: hidden;
}

.proj-details__team-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent), var(--accent));
  border-radius: 2px;
  transition: width 0.4s ease;
}

/* ── Tables ── */
.proj-details__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.proj-details__table th {
  text-align: left;
  font-size: 11px;
  font-weight: 600;
  color: var(--color-text-muted, #9ca3af);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--color-border, #e5e7eb);
}

.proj-details__table td {
  padding: 8px 10px;
  color: var(--color-text-primary, #1a1a2e);
  border-bottom: 1px solid var(--bg-subtle);
}

.proj-details__table tbody tr:last-child td {
  border-bottom: none;
}

/* ── #6 Summary strip ── */
.proj-details__tb-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 16px;
}

.proj-details__tb-summary-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 14px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 20px;
  background: var(--bg-card);
  font-size: 12px;
  font-weight: 600;
  color: var(--color-text-primary, #1a1a2e);
  cursor: pointer;
  transition: all 0.15s;
}

.proj-details__tb-summary-pill:hover {
  background: var(--bg-subtle);
}

.proj-details__tb-summary-pill--active {
  border-color: var(--accent);
  background: var(--accent-bg);
}

.proj-details__tb-summary-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.proj-details__tb-summary-dot--danger {
  background: var(--color-danger);
}
.proj-details__tb-summary-dot--warning {
  background: var(--chart-4);
}
.proj-details__tb-summary-dot--success {
  background: var(--color-success);
}
.proj-details__tb-summary-dot--info {
  background: var(--accent);
}
.proj-details__tb-summary-dot--sign {
  background: var(--color-badge-warning-text);
}

/* The one pill that is tinted rather than neutral: a signature is the only
   row in this table that asks the viewer personally to do something. */
.proj-details__tb-summary-pill--sign {
  background: var(--color-badge-warning-bg);
  border-color: var(--color-badge-warning-text);
  color: var(--color-badge-warning-text);
}
.proj-details__tb-summary-pill--sign:hover {
  background: var(--color-badge-warning-bg);
  filter: brightness(0.97);
}

/* ── #6 Sortable headers ── */
.proj-details__th-sort {
  cursor: pointer;
  user-select: none;
  transition: color 0.15s;
}

.proj-details__th-sort:hover {
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__th-sort--active {
  color: var(--accent) !important;
}

.proj-details__sort-arrow {
  font-size: 10px;
  margin-left: 2px;
}

/* ── Task Browser ── */
.proj-details__tb-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 16px;
}

.proj-details__tb-filter {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1;
  min-width: 120px;
  max-width: 200px;
}

.proj-details__tb-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--color-text-muted, #9ca3af);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.proj-details__tb-input,
.proj-details__tb-select {
  padding: 7px 10px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 8px;
  font-size: 13px;
  color: var(--color-text-primary, #1a1a2e);
  background: var(--bg-card);
  outline: none;
  transition: border-color 0.15s;
}

.proj-details__tb-input:focus,
.proj-details__tb-select:focus {
  border-color: var(--accent);
}

.proj-details__tb-input--date {
  min-width: 130px;
  font-size: 12px;
}

/* ── Date Range Picker ── */
.proj-details__date-filter-row {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  margin-bottom: 16px;
}

.proj-details__date-range {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 6px;
  background: var(--color-main-background, #fff);
  cursor: pointer;
  font-size: 12px;
  min-width: 180px;
  transition: border-color 0.15s;
}

.proj-details__date-range:hover {
  border-color: var(--accent);
}

.proj-details__date-range-value {
  color: var(--color-text-primary, #1a1a2e);
  font-weight: 500;
  min-width: 70px;
  text-align: center;
}

.proj-details__date-range-value:empty,
.proj-details__date-range-value:not(:empty) {
  /* ensure placeholder text visible */
}

.proj-details__date-range-arrow {
  color: var(--color-text-muted, #9ca3af);
  font-size: 13px;
}

.proj-details__date-range-clear {
  margin-left: auto;
  background: none;
  border: none;
  color: var(--color-text-muted, #9ca3af);
  cursor: pointer;
  font-size: 13px;
  line-height: 1;
  padding: 0 2px;
}

.proj-details__date-range-clear:hover {
  color: var(--color-danger);
}

.proj-details__date-picker-dropdown {
  display: inline-flex;
  flex-direction: column;
  margin-bottom: 12px;
  background: var(--color-main-background, #fff);
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 10px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  padding: 12px 14px 8px;
  min-width: 460px;
  width: fit-content;
}

.proj-details__date-picker-months {
  display: flex;
  gap: 16px;
}

.proj-details__date-picker-month {
  flex: 1;
  min-width: 200px;
}

.proj-details__date-picker-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.proj-details__date-picker-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__date-picker-nav {
  background: none;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 4px;
  width: 24px;
  height: 24px;
  cursor: pointer;
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--color-text-primary, #1a1a2e);
  transition: background 0.15s;
}

.proj-details__date-picker-nav:hover {
  background: var(--color-background-hover, #f3f4f6);
}

.proj-details__date-picker-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px 0;
  text-align: center;
}

.proj-details__date-picker-dow {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-text-muted, #9ca3af);
  padding: 2px 0 4px;
  text-transform: uppercase;
}

.proj-details__date-picker-cell {
  font-size: 12px;
  padding: 5px 0;
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__date-picker-cell:hover {
  background: var(--color-background-hover, #f3f4f6);
}

.proj-details__date-picker-cell--empty {
  cursor: default;
}

.proj-details__date-picker-cell--today {
  font-weight: 700;
  text-decoration: underline;
}

.proj-details__date-picker-cell--start {
  background: var(--accent) !important;
  color: #fff !important;
  border-radius: 6px 0 0 6px;
}

.proj-details__date-picker-cell--end {
  background: var(--accent) !important;
  color: #fff !important;
  border-radius: 0 6px 6px 0;
}

.proj-details__date-picker-cell--solo {
  background: var(--accent) !important;
  color: #fff !important;
  border-radius: 6px;
}

.proj-details__date-picker-cell--in-range {
  background: color-mix(in oklab, var(--accent) 15%, transparent);
}

.proj-details__date-picker-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px solid var(--color-border, #e5e7eb);
}

.proj-details__date-picker-btn {
  padding: 4px 14px;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 6px;
  background: var(--color-main-background, #fff);
  font-size: 12px;
  cursor: pointer;
  color: var(--color-text-primary, #1a1a2e);
}

.proj-details__date-picker-btn:hover {
  background: var(--color-background-hover, #f3f4f6);
}

.proj-details__date-picker-btn--apply {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.proj-details__date-picker-btn--apply:hover {
  background: var(--accent-hover);
}

.proj-details__tb-count {
  font-size: 12px;
  color: var(--color-text-muted, #9ca3af);
  margin-bottom: 8px;
}

.proj-details__tb-table-wrap {
  overflow-x: auto;
  border: 1px solid var(--color-border, #e5e7eb);
  border-radius: 8px;
}

.proj-details__tb-table th {
  background: var(--bg-subtle);
  white-space: nowrap;
}
.proj-details__tb-table tbody tr:hover {
  background: var(--bg-subtle);
}

/* Signature rows: a left edge and a tint so they read as a different kind of
   work without breaking the table's rhythm. */
.proj-details__tb-row--sign > td {
  background: var(--color-badge-warning-bg);
}
.proj-details__tb-row--sign > td:first-child {
  box-shadow: inset 3px 0 0 var(--color-badge-warning-text);
}
.proj-details__tb-sign-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--color-text-primary);
  text-decoration: none;
  border-bottom: 1px solid transparent;
}
.proj-details__tb-sign-link:hover {
  border-bottom-color: var(--color-badge-warning-text);
}
.proj-details__tb-sign-link svg {
  flex-shrink: 0;
  color: var(--color-badge-warning-text);
}
.proj-details__tb-cell-title {
  font-weight: 500;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.proj-details__tb-stack-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  background: var(--accent-bg);
  color: var(--accent);
  white-space: nowrap;
